package com.habilitesrandom;
import com.habilitesrandom.api.*;import com.habilitesrandom.randomizer.*;import net.minecraft.resources.Identifier;import org.junit.jupiter.api.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class RandomizerSystemsTest {
 record Item(String id,double weight){}
 @Test void weightsNormalizeAndDeterministicallySelect(){var items=List.of(new Item("a",100),new Item("b",50),new Item("c",10));assertEquals(.625,WeightedRandomSelector.chance(items.get(0),items,Item::weight),1e-9);var rng=new java.util.Random(42);var counts=new HashMap<String,Integer>();for(int i=0;i<20000;i++)counts.merge(WeightedRandomSelector.select(items,Item::weight,rng).id(),1,Integer::sum);assertTrue(counts.get("a")>counts.get("b"));assertTrue(counts.get("b")>counts.get("c"));}
 @Test void rejectsMalformedWeights(){assertThrows(IllegalArgumentException.class,()->WeightedRandomSelector.select(List.of(new Item("x",-1)),Item::weight,new Random()));assertThrows(IllegalArgumentException.class,()->WeightedRandomSelector.select(List.<Item>of(),Item::weight,new Random()));}
 @Test void antiLuckIsBoundedAndDoesNotChangeRarity(){var weak=character("weak",StrengthCategory.WEAK);var strong=character("strong",StrengthCategory.STRONG);assertEquals(1,AntiLuckPolicy.multiplier(weak,99,true));assertEquals(1.22,AntiLuckPolicy.multiplier(strong,3,true));assertEquals(2,AntiLuckPolicy.multiplier(strong,7,true));assertEquals(0,AntiLuckPolicy.nextStreak(8,strong));assertEquals(9,AntiLuckPolicy.nextStreak(8,weak));assertEquals(weak.rarityId(),character("weak",StrengthCategory.WEAK).rarityId());}
 private CharacterDefinition character(String id,StrengthCategory category){Identifier base=HabilitesRandom.id(id);return new CharacterDefinition(base,id,HabilitesRandom.id("anime"),HabilitesRandom.id("divine"),category,1,"",List.of(HabilitesRandom.id(id+"/1"),HabilitesRandom.id(id+"/2"),HabilitesRandom.id(id+"/3"),HabilitesRandom.id(id+"/4")),HabilitesRandom.id(id+"/form"),"","");}
}
